const VERSION='rol-v1.0.2';const SHELL=['./','./index.html','./style.css','./app.js','./model.js','./store.js','./sync.js','./export.js','./importer.js','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png','./logo.png'];
self.addEventListener('install',e=>e.waitUntil(caches.open(VERSION).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('rol-v')&&k!==VERSION).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin)return;const scope=new URL(self.registration.scope);if(!u.pathname.startsWith(scope.pathname))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(VERSION).then(c=>c.put(e.request,copy));}return r;}).catch(async()=>{const cached=await caches.match(e.request);if(cached)return cached;if(e.request.mode==='navigate')return caches.match('./index.html');return Response.error();}));});
self.addEventListener('push',e=>{let data={title:'Rol de monaguillos',body:'Revisa la participación de esta semana.'};try{data={...data,...e.data.json()};}catch{}e.waitUntil(self.registration.showNotification(data.title,{body:data.body,icon:'./icon-192.png',badge:'./icon-192.png',tag:data.tag||'rol-participacion',data:{week:data.week||null}}));});
self.addEventListener('notificationclick',e=>{e.notification.close();const u=new URL('./',self.registration.scope);if(e.notification.data?.week)u.searchParams.set('week',e.notification.data.week);e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(async tabs=>{const tab=tabs.find(t=>t.url.startsWith(self.registration.scope));if(tab){await tab.navigate(u.href);return tab.focus();}return clients.openWindow(u.href);}));});
